using System;using System.Drawing;using System.IO;using System.Reflection;using System.Threading.Tasks;using System.Windows.Forms;
namespace Captura {
 static class UiRegression {
  static T Field<T>(object o,string name){return (T)o.GetType().GetField(name,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(o);}
  static void Set(object o,string name,object value){o.GetType().GetField(name,BindingFlags.Instance|BindingFlags.NonPublic).SetValue(o,value);}
  static void Select(DarkChoice choice,int index){choice.PerformClick();Application.DoEvents();var menu=choice.ActiveMenu;if(menu==null||menu.IsDisposed||!menu.Visible)throw new Exception("Seletor não abriu");menu.Items[index].PerformClick();menu.Close();Application.DoEvents();if(menu.IsDisposed)throw new Exception("Menu descartado durante fechamento");if(choice.SelectedIndex!=index)throw new Exception("Seleção não aplicada");}
  public static void Run(){string log=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"ui-test.txt");string output=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"ui-recordings-"+DateTime.Now.ToString("yyyyMMdd-HHmmss"));using(var host=new Form{Text="Priint UI TEST TARGET",ClientSize=new Size(640,360),Location=new Point(70,70),StartPosition=FormStartPosition.Manual,BackColor=Color.Navy}){host.Shown+=async delegate{RecorderForm studio=null;try{host.Hide();host.Show();Application.DoEvents();studio=new RecorderForm{Testing=true};studio.Show();Application.DoEvents();var mode=Field<DarkChoice>(studio,"mode");var source=Field<DarkChoice>(studio,"source");var encoder=Field<DarkChoice>(studio,"encoder");var fps=Field<FpsChoice>(studio,"fps");
   for(int repeat=0;repeat<5;repeat++){for(int i=0;i<4;i++){Select(mode,i);if((i==1||i==2)&&source.Items.Count>0)Select(source,0);}Select(encoder,1);Select(encoder,0);}
   Select(mode,3);Field<CheckBox>(studio,"camera").Checked=true;Select(mode,0);if(Field<CheckBox>(studio,"camera").Checked||Field<CheckBox>(studio,"camera").Enabled)throw new Exception("Câmera permitida em área");
   foreach(int n in new[]{30,60,120,240}){fps.Value=n;if(fps.Value!=n)throw new Exception("FPS não aplicado");}fps.Value=30;Field<TextBox>(studio,"folder").Text=output;
   for(int m=0;m<4;m++){studio.Show();Select(mode,m);if(m==0){Set(studio,"region",new Rectangle(host.Left+20,host.Top+50,320,180));mode.SelectedIndex=0;fps.Value=60;}else fps.Value=30;
    if(m==2){int target=-1;for(int i=0;i<source.Items.Count;i++){var candidate=source.Items[i] as SourceChoice;if(candidate!=null&&candidate.Handle==host.Handle)target=i;}if(target<0)throw new Exception("Janela alvo ausente");Select(source,target);}
    var record=Field<Button>(studio,"record");if(!record.Enabled)throw new Exception("Gravar desabilitado para modo "+m);File.AppendAllText(log,"Starting mode "+m+Environment.NewLine);record.PerformClick();File.AppendAllText(log,"Start clicked"+Environment.NewLine);DateTime readyDeadline=DateTime.Now.AddSeconds(20);while(studio.Preparing&&DateTime.Now<readyDeadline)await Task.Delay(50);await Task.Delay(1100);File.AppendAllText(log,"Delay done"+Environment.NewLine);if(!studio.ActiveRecording)throw new Exception("Gravação não iniciou: "+Field<Label>(studio,"status").Text);studio.Show();File.AppendAllText(log,"Stop enabled="+Field<Button>(studio,"stop").Enabled+" visible="+Field<Button>(studio,"stop").Visible+Environment.NewLine);Field<Button>(studio,"stop").PerformClick();File.AppendAllText(log,"Stop clicked"+Environment.NewLine);DateTime deadline=DateTime.Now.AddSeconds(25);while(studio.ActiveRecording&&DateTime.Now<deadline)await Task.Delay(100);if(studio.ActiveRecording)throw new Exception("Parada travou");string file=Field<RecordingEngine>(studio,"engine").OutputPath;if(string.IsNullOrEmpty(file)||!File.Exists(file))throw new Exception("Sem arquivo válido no modo "+m);File.AppendAllText(log,"UI modo "+m+" gravou/parou/validou: "+Path.GetFileName(file)+Environment.NewLine);
   }
   using(var opts=new OptionsForm(new Preferences(),delegate(Preferences p){return null;})){opts.Show();Application.DoEvents();foreach(Control c in opts.Controls)if(c is SectionTabs)((SectionTabs)c).SelectPage(2);Application.DoEvents();var format=Field<DarkChoice>(opts,"format");Select(format,1);Select(format,0);foreach(Control c in opts.Controls)if(c is SectionTabs)((SectionTabs)c).SelectPage(3);Field<FpsChoice>(opts,"videoFps").Value=120;if(Field<FpsChoice>(opts,"videoFps").Value!=120)throw new Exception("FPS nas opções falhou");opts.Dispose();}
   File.AppendAllText(log,"OK: 20 trocas de modo, seletores abrem/fecham/reabrem, monitor/janela, FPS30/60/120/240, câmera restrita por modo, 4 gravações pela UI, opções de vídeo."+Environment.NewLine);
  }catch(Exception ex){File.AppendAllText(log,"FAIL: "+ex+Environment.NewLine);Environment.ExitCode=1;}finally{if(studio!=null)studio.Dispose();host.Close();}};File.WriteAllText(log,"");host.ShowDialog();}}
 }
}

